public static class FibreCompatibilityChecks {
 [Serializable]class Report {public bool pass;public string error;public List<string> checks=new List<string>();public List<string> fixedImages=new List<string>();}
 static Report report;
 static HashSet<string> nativeIds;
 static int NativeCount(string source){return File.ReadAllLines(Path.Combine(source,"props.csv")).Count(line=>{var row=line.Split(',');return row.Length==11&&nativeIds.Contains(row[1]);});}
 static string Arg(string flag){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,flag)+1];}
 static void Check(string name,bool ok){if(!ok)throw new Exception(name);report.checks.Add(name);}
 static string Folder(string prefix){string p=AssetDatabase.GenerateUniqueAssetPath("Assets/"+prefix);AssetDatabase.CreateFolder("Assets",Path.GetFileName(p));return p;}
 static Dictionary<string,string> Snapshot(string source){var result=new Dictionary<string,string>();foreach(string name in new[]{"small_props.json","props.csv","asset_catalog.json","asset_bindings.json"}){string p=Path.Combine(source,name);if(File.Exists(p))result[name]=SharedAssetFiles.Hash(File.ReadAllBytes(p));}return result;}
 static GameObject Fixture(string id,string folder){
  var o=GameObject.CreatePrimitive(id=="tiedsack"?PrimitiveType.Capsule:PrimitiveType.Cube);o.name="Authored external "+id;o.transform.localScale=Vector3.one;
  var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.SetColor("_BaseColor",id=="tiedsack"?new Color(.15f,.3f,.8f):new Color(.8f,.2f,.12f));AssetDatabase.CreateAsset(m,folder+"/"+id+".mat");o.GetComponent<Renderer>().sharedMaterial=m;
  var child=new GameObject("Authored offset");child.transform.SetParent(o.transform,false);child.transform.localPosition=new Vector3(.12f,.23f,.04f);
  var prefab=PrefabUtility.SaveAsPrefabAsset(o,folder+"/"+id+".prefab");UnityEngine.Object.DestroyImmediate(o);return prefab;
 }
 static void VerifyRows(string source,Transform root,string id,GameObject prefab){int count=0;foreach(string line in File.ReadAllLines(Path.Combine(source,"props.csv"))){var row=line.Split(',');if(row.Length!=11||row[1]!=id||row[2]=="tdj/"+id)continue;var o=root.Find(row[0]);Check(row[0]+" resolves the actual supplied prefab",o&&PrefabUtility.GetCorrespondingObjectFromSource(o.gameObject)==prefab);float N(int k){return float.Parse(row[k],System.Globalization.CultureInfo.InvariantCulture);}Check(row[0]+" exact source transform",Vector3.Distance(o.localPosition,new Vector3(N(3),N(4),N(5)))<.000001f&&Quaternion.Angle(o.localRotation,Quaternion.Euler(0,N(6),0))<.001f&&Vector3.Distance(o.localScale,new Vector3(N(7),N(8),N(7)))<.000001f);Check(row[0]+" authored mesh material collider and child preserved",o.GetComponent<MeshFilter>().sharedMesh==prefab.GetComponent<MeshFilter>().sharedMesh&&o.GetComponent<Renderer>().sharedMaterial==prefab.GetComponent<Renderer>().sharedMaterial&&o.GetComponent<Collider>().GetType()==prefab.GetComponent<Collider>().GetType()&&o.Find("Authored offset").localPosition==new Vector3(.12f,.23f,.04f));count++;}Check(id+" external instances are actually generated",count>0);}
 public static void Run(){report=new Report();int code=0;string output=Arg("-props-output"),baseDir=Arg("-props-root");Directory.CreateDirectory(output);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
  var rd=ScriptableObject.CreateInstance<UnityEngine.Rendering.Universal.UniversalRendererData>();var rp=UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  nativeIds=new HashSet<string>(SmallPropsV1.Read(Path.Combine(baseDir,"batch23-release-regression/after-export/small_props.json")).assets.Select(a=>a.id));var fixtureFolder=Folder("FibreExternalFixtures");
  foreach(string id in new[]{"tiedsack","coiledrope"}){
   var prefab=Fixture(id,fixtureFolder);string suffix=id=="tiedsack"?"sack":"rope";var external=new Dictionary<string,GameObject>{{"custom/night-"+id,prefab}};
   foreach(string version in (Array.IndexOf(Environment.GetCommandLineArgs(),"-props-current-only")>=0?new[]{"current"}:Array.IndexOf(Environment.GetCommandLineArgs(),"-props-current-custom-root")>=0?new[]{"17f405e","541d18e","current"}:new[]{"17f405e","541d18e"})){
    string source=version=="current"?Path.Combine(Arg("-props-current-custom-root"),"custom-"+suffix):Path.Combine(baseDir,version=="17f405e"?"batch24-before-custom-"+suffix:"batch23-release-custom-"+suffix);var snapshot=Snapshot(source);
    bool rejected=false;int roots=UnityEngine.Object.FindObjectsByType<Transform>().Length;try{MapSharedPropsBuilder.Build(source);}catch(InvalidDataException e){rejected=e.Message.Contains("External fibre prefab unresolved")&&e.Message.Contains("custom/night-"+id);}Check(version+" "+id+" unresolved mapping fails visibly before scene changes",rejected&&roots==UnityEngine.Object.FindObjectsByType<Transform>().Length);
    var current=MapSharedPropsBuilder.Build(source,null,external);Check(version+" "+id+" new full builder places every row",current.placed==99&&current.skipped==0&&!current.prefabs.ContainsKey(id));VerifyRows(source,current.root.transform,id,prefab);current.root.SetActive(false);
    var oldFolder=Folder("FibreLegacyBridge");var oldRoot=new GameObject("Legacy bridge "+version+" "+id);var prefabs=new Dictionary<string,GameObject>();int placed=FibrePrefabImport.Build(source,oldFolder,oldRoot.transform,Shader.Find("MapSharedProps/Lit"),prefabs,external,PreFibreSmallPropsV1.Build);Check(version+" "+id+" frozen old reader plus explicit bridge places every supported Native row",placed==NativeCount(source)&&oldRoot.transform.childCount==NativeCount(source)&&!prefabs.ContainsKey(id));VerifyRows(source,oldRoot.transform,id,prefab);oldRoot.SetActive(false);
    Check(version+" "+id+" source export files remain byte exact",snapshot.All(k=>Snapshot(source)[k.Key]==k.Value));
    var rootId=current.root.GetEntityId();Undo.RegisterCreatedObjectUndo(current.root,"External fibre import proof");Undo.FlushUndoRecordObjects();Undo.PerformUndo();Check(version+" "+id+" imported root supports Undo",!current.root);Undo.PerformRedo();var restored=EditorUtility.EntityIdToObject(rootId) as GameObject;Check(version+" "+id+" Redo restores the same imported root",restored);VerifyRows(source,restored.transform,id,prefab);restored.SetActive(false);Undo.ClearAll();
   }
   // In-memory intake copy: one canonical row plus two custom rows, then a compact-library variant.
   string original=Array.IndexOf(Environment.GetCommandLineArgs(),"-props-current-custom-root")>=0?Path.Combine(Arg("-props-current-custom-root"),"custom-"+suffix):Path.Combine(baseDir,"batch23-release-custom-"+suffix),view=Path.Combine(Path.GetTempPath(),"FibreMixedProof-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(view);try{
    var lines=File.ReadAllLines(Path.Combine(original,"props.csv"));bool first=true;for(int k=0;k<lines.Length;k++){var row=lines[k].Split(',');if(row.Length==11&&row[1]==id&&first){row[2]="tdj/"+id;lines[k]=string.Join(",",row);first=false;}}File.WriteAllLines(Path.Combine(view,"props.csv"),lines);string raw=File.ReadAllText(Path.Combine(original,"small_props.json"));File.WriteAllText(Path.Combine(view,"small_props.json"),raw);
    foreach(bool compact in new[]{false,true}){if(compact){File.WriteAllText(Path.Combine(view,"small_props_library.json"),raw);File.WriteAllText(Path.Combine(view,"small_props.json"),"{\"version\":1,\"units\":\"metres\",\"axes\":\"Unity X/Y/Z\",\"library\":\"small_props_library.json\",\"instances\":"+Extract(raw,"instances")+",\"grounded\":"+Extract(raw,"grounded")+"}");}foreach(bool legacy in new[]{true,false}){var root=new GameObject("Mixed "+id+" "+compact+" "+legacy);var prefabs=new Dictionary<string,GameObject>();int placed=legacy?FibrePrefabImport.Build(view,Folder("FibreMixedLegacy"),root.transform,Shader.Find("MapSharedProps/Lit"),prefabs,external,PreFibreSmallPropsV1.Build):SmallPropsV1.Build(view,Folder("FibreMixedCurrent"),root.transform,Shader.Find("MapSharedProps/Lit"),prefabs,external);Check(id+" mixed canonical/custom compact="+compact+" legacy="+legacy,placed==NativeCount(view)&&root.transform.childCount==NativeCount(view)&&prefabs.ContainsKey(id));VerifyRows(view,root.transform,id,prefab);var canonical=root.transform.Find("custom-"+id+"-0");Check(id+" canonical row remains standard, never custom alias",PrefabUtility.GetCorrespondingObjectFromSource(canonical.gameObject)==prefabs[id]&&canonical.GetComponent<Renderer>().sharedMaterial.shader.name==(legacy?"MapSharedProps/Lit":"MapSharedProps/FibreProp"));root.SetActive(false);}}
   }finally{Directory.Delete(view,true);}
  }
  EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/FibreCompatibilityProof.unity");EditorSceneManager.OpenScene("Assets/FibreCompatibilityProof.unity");var reloaded=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include).Where(t=>t.name.StartsWith("custom-tiedsack-")||t.name.StartsWith("custom-coiledrope-")).ToArray();Check("all external and canonical prefab source links survive scene save/reload",reloaded.Length>=24&&reloaded.All(t=>PrefabUtility.GetCorrespondingObjectFromSource(t.gameObject)!=null));
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);FixedChestImages(baseDir,output);report.pass=true;
 }catch(Exception e){report.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"compatibility.json"),JsonUtility.ToJson(report,true));if(code==0&&Array.IndexOf(Environment.GetCommandLineArgs(),"-props-followup-night")>=0)NightPropsChecks.Run();else EditorApplication.Exit(code);}}
 // Copy a top-level JSON value verbatim, preserving the compact sidecar's existing data arrays.
 static string Extract(string text,string key){int start=text.IndexOf("\""+key+"\":",StringComparison.Ordinal)+key.Length+3;int depth=0;bool quoted=false,escape=false;for(int i=start;i<text.Length;i++){char c=text[i];if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;continue;}if(c=='"')quoted=true;else if(c=='['||c=='{')depth++;else if(c==']'||c=='}'){depth--;if(depth==0)return text.Substring(start,i-start+1);}}throw new Exception("Missing JSON value "+key);}
 public static void RunFixed(){report=new Report();int code=0;string output=Arg("-props-output");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UnityEngine.Rendering.Universal.UniversalRendererData>();var rp=UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;FixedChestImages(Arg("-props-root"),output);report.pass=true;}catch(Exception e){report.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"compatibility.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
 static void FixedChestImages(string baseDir,string output){
  RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;floor.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit"));floor.GetComponent<Renderer>().sharedMaterial.SetColor("_BaseColor",new Color(.22f,.17f,.11f));var camera=new GameObject("Fixed camera").AddComponent<Camera>();camera.gameObject.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.aspect=1.28f;camera.backgroundColor=Color.black;camera.clearFlags=CameraClearFlags.SolidColor;camera.targetTexture=new RenderTexture(1280,1000,24,RenderTextureFormat.ARGB32);camera.nearClipPlane=.3f;
  var stages=new Dictionary<string,Dictionary<string,GameObject>>();foreach(string stage in new[]{"before","after"}){string source=Path.Combine(baseDir,"batch23-release-regression",stage+"-export");var root=new GameObject(stage+" Native");var prefabs=new Dictionary<string,GameObject>();if(stage=="before")PreFibreSmallPropsV1.Build(source,Folder("FibreFixedBefore"),root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);else SmallPropsV1.Build(source,Folder("FibreFixedAfter"),root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);root.SetActive(false);stages[stage]=prefabs;}
  foreach(string file in new[]{"treasurechest_gold-time0","treasurechest_gold-time1","treasurechest_gold-top","treasurechest_rainbow-detail","treasurechest_rainbow-time0","treasurechest_rainbow-time1","treasurechest_rainbow-top"}){
   var bytes=new List<byte[]>();string id=file.StartsWith("treasurechest_gold")?"treasurechest_gold":"treasurechest_rainbow";float time=file.EndsWith("time1")?1:0;foreach(string stage in new[]{"before","after"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(stages[stage][id]);foreach(var r in o.GetComponentsInChildren<Renderer>())if(r.sharedMaterial.HasProperty("_ChestTime"))r.sharedMaterial.SetFloat("_ChestTime",time);var fx=o.GetComponent<ChestPresentation>();fx.SetSeed("batch24-fixed-"+id);fx.SetTime(time);float target=.71f*.42f;camera.transform.position=file.EndsWith("top")?new Vector3(0,17,0):file.Contains("-time")?new Vector3(1.32f,1.09f,-1.76f):new Vector3(1.32f,target+.77f,-1.76f);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,file.Contains("-time")?.33f:target,0)-camera.transform.position,file.EndsWith("top")?Vector3.forward:Vector3.up);for(int warm=0;warm<3;warm++)camera.Render();var old=RenderTexture.active;RenderTexture.active=camera.targetTexture;var png=new Texture2D(1280,1000,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1280,1000),0,0);png.Apply();var data=png.EncodeToPNG();bytes.Add(data);string dir=Path.Combine(output,"fixed-"+stage);Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,file+".png"),data);UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(o);}Check(file+" fixed camera/light/seed/root time/FX time byte exact",bytes[0].SequenceEqual(bytes[1]));report.fixedImages.Add(file);}
  foreach(string id in new[]{"treasurechest_gold","treasurechest_rainbow"}){var a=File.ReadAllBytes(Path.Combine(output,"fixed-after",id+"-time0.png"));var b=File.ReadAllBytes(Path.Combine(output,"fixed-after",id+"-time1.png"));Check(id+" fixed times still produce animated pixels",!a.SequenceEqual(b));}
 }
